/** Normalize a program-of-record string to the alias comparison form. */
function normalizeProgramText(s: string | null | undefined): string {
  return (s ?? '')
    .toUpperCase()
    .replace(/[‐-―−]/g, '-')
    .replace(/[^A-Z0-9]+/g, ' ')
    .replace(/s+/g, ' ')
    .trim();
}

