      const decision = classifyRoleStaleness({
        observedAt: r.observedAt,
        staleAt: r.staleAt,
        now,
        thresholdDays,
      });
      if (decision.action === 'mark_stale') {
        toMark.push(r);
      } else if (decision.action === 'keep') {
        kept += 1;
      } else {
        skipped += 1;
      }
    }

    const capped = limit > 0 ? toMark.slice(0, limit) : toMark;

    let marked = 0;
