export function ingestionManifestExitCodeV1(outcome: string): number {
  if (outcome === 'preview' || outcome === 'completed' || outcome === 'stopped' || outcome === 'reconciled') return 0;
  if (outcome === 'uncertain') return 4;
  return 3;
}

