function realHighWaterMark(prisma: PrismaClient): DibbsSyncDeps['highWaterMark'] {
  return async (endpoint) => {
    if (endpoint === 'award') {
      const row = await prisma.tangoDibbsAward.aggregate({
        _max: { postedDate: true },
